// --- acr_tui.FDb.window.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
acr_tui::FWindow& acr_tui::window_Alloc() {
    acr_tui::FWindow* row = window_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("acr_tui.out_of_mem  field:acr_tui.FDb.window  comment:'Alloc failed'");
    }
    return *row;
}

// --- acr_tui.FDb.window.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
acr_tui::FWindow* acr_tui::window_AllocMaybe() {
    acr_tui::FWindow *row = (acr_tui::FWindow*)window_AllocMem();
    if (row) {
        new (row) acr_tui::FWindow; // call constructor
    }
    return row;
}

// --- acr_tui.FDb.window.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
acr_tui::FWindow* acr_tui::window_InsertMaybe(const ui::Window &value) {
    acr_tui::FWindow *row = &window_Alloc(); // if out of memory, process dies. if input error, return NULL.
    window_CopyIn(*row,const_cast<ui::Window&>(value));
    bool ok = window_XrefMaybe(*row); // this may return false
    if (!ok) {
        window_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- acr_tui.FDb.window.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* acr_tui::window_AllocMem() {
    u64 new_nelems     = _db.window_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    acr_tui::FWindow*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.window_lary[bsr];
        if (!lev) {
            lev=(acr_tui::FWindow*)algo_lib::malloc_AllocMem(sizeof(acr_tui::FWindow) * (u64(1)<<bsr));
            _db.window_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.window_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- acr_tui.FDb.window.RemoveAll
// Remove all elements from Lary
void acr_tui::window_RemoveAll() {
    for (u64 n = _db.window_n; n>0; ) {
        n--;
        window_qFind(u64(n)).~FWindow(); // destroy last element
        _db.window_n = i32(n);
    }
}

// --- acr_tui.FDb.window.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void acr_tui::window_RemoveLast() {
    u64 n = _db.window_n;
    if (n > 0) {
        n -= 1;
        window_qFind(u64(n)).~FWindow();
        _db.window_n = i32(n);
    }
}

// --- acr_tui.FDb.window.InputMaybe
static bool acr_tui::window_InputMaybe(ui::Window &elem) {
    bool retval = true;
    retval = window_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- acr_tui.FDb.window.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool acr_tui::window_XrefMaybe(acr_tui::FWindow &row) {
    bool retval = true;
    (void)row;
    // insert window into index ind_window
    if (true) { // user-defined insert condition
        bool success = ind_window_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "acr_tui.duplicate_key  xref:acr_tui.FDb.ind_window"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

// --- acr_tui.FDb.ind_window.Find
// Find row by key. Return NULL if not found.
acr_tui::FWindow* acr_tui::ind_window_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_window_buckets_n - 1);
    acr_tui::FWindow *ret = _db.ind_window_buckets_elems[index];
    for (; ret && !((*ret).window == key); ret = ret->ind_window_next) {
    }
    return ret;
}

// --- acr_tui.FDb.ind_window.FindX
// Look up row by key and return reference. Throw exception if not found
acr_tui::FWindow& acr_tui::ind_window_FindX(const algo::strptr& key) {
    acr_tui::FWindow* ret = ind_window_Find(key);
    vrfy(ret, tempstr() << "acr_tui.key_error  table:ind_window  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- acr_tui.FDb.ind_window.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
acr_tui::FWindow& acr_tui::ind_window_GetOrCreate(const algo::strptr& key) {
    acr_tui::FWindow* ret = ind_window_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &window_Alloc();
        (*ret).window = key;
        bool good = window_XrefMaybe(*ret);
        if (!good) {
            window_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "acr_tui.create_error  table:ind_window  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- acr_tui.FDb.ind_window.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool acr_tui::ind_window_InsertMaybe(acr_tui::FWindow& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_window_next == (acr_tui::FWindow*)-1)) {// check if in hash already
        row.ind_window_hashval = algo::Smallstr50_Hash(0, row.window);
        ind_window_Reserve(1);
        u32 index = row.ind_window_hashval & (_db.ind_window_buckets_n - 1);
        acr_tui::FWindow* *prev = &_db.ind_window_buckets_elems[index];
        do {
            acr_tui::FWindow* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).window == row.window) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_window_next;
        } while (true);
        if (retval) {
            row.ind_window_next = *prev;
            _db.ind_window_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- acr_tui.FDb.ind_window.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void acr_tui::ind_window_Remove(acr_tui::FWindow& row) {
    if (LIKELY(row.ind_window_next != (acr_tui::FWindow*)-1)) {// check if in hash already
        u32 index = row.ind_window_hashval & (_db.ind_window_buckets_n - 1);
        acr_tui::FWindow* *prev = &_db.ind_window_buckets_elems[index]; // addr of pointer to current element
        while (acr_tui::FWindow *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_window_next; // unlink (singly linked list)
                _db.ind_window_n--;
                row.ind_window_next = (acr_tui::FWindow*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_window_next;
        }
    }
}

// --- acr_tui.FDb.ind_window.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void acr_tui::ind_window_Reserve(int n) {
    ind_window_AbsReserve(_db.ind_window_n + n);
}

// --- acr_tui.FDb.ind_window.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void acr_tui::ind_window_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_window_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(acr_tui::FWindow*);
        u32 new_size = new_nbuckets * sizeof(acr_tui::FWindow*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        acr_tui::FWindow* *new_buckets = (acr_tui::FWindow**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("acr_tui.out_of_memory  field:acr_tui.FDb.ind_window");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_window_buckets_n; i++) {
            acr_tui::FWindow* elem = _db.ind_window_buckets_elems[i];
            while (elem) {
                acr_tui::FWindow &row        = *elem;
                acr_tui::FWindow* next       = row.ind_window_next;
                u32 index          = row.ind_window_hashval & (new_nbuckets-1);
                row.ind_window_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_window_buckets_elems, old_size);
        _db.ind_window_buckets_elems = new_buckets;
        _db.ind_window_buckets_n = new_nbuckets;
    }
}

