// --- acr_tui.FDb.ind_style.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool acr_tui::ind_style_InsertMaybe(acr_tui::FStyle& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_style_next == (acr_tui::FStyle*)-1)) {// check if in hash already
        row.ind_style_hashval = algo::Smallstr50_Hash(0, row.style);
        ind_style_Reserve(1);
        u32 index = row.ind_style_hashval & (_db.ind_style_buckets_n - 1);
        acr_tui::FStyle* *prev = &_db.ind_style_buckets_elems[index];
        do {
            acr_tui::FStyle* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).style == row.style) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_style_next;
        } while (true);
        if (retval) {
            row.ind_style_next = *prev;
            _db.ind_style_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- acr_tui.FDb.ind_style.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void acr_tui::ind_style_Remove(acr_tui::FStyle& row) {
    if (LIKELY(row.ind_style_next != (acr_tui::FStyle*)-1)) {// check if in hash already
        u32 index = row.ind_style_hashval & (_db.ind_style_buckets_n - 1);
        acr_tui::FStyle* *prev = &_db.ind_style_buckets_elems[index]; // addr of pointer to current element
        while (acr_tui::FStyle *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_style_next; // unlink (singly linked list)
                _db.ind_style_n--;
                row.ind_style_next = (acr_tui::FStyle*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_style_next;
        }
    }
}

// --- acr_tui.FDb.ind_style.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void acr_tui::ind_style_Reserve(int n) {
    ind_style_AbsReserve(_db.ind_style_n + n);
}

// --- acr_tui.FDb.ind_style.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void acr_tui::ind_style_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_style_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(acr_tui::FStyle*);
        u32 new_size = new_nbuckets * sizeof(acr_tui::FStyle*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        acr_tui::FStyle* *new_buckets = (acr_tui::FStyle**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("acr_tui.out_of_memory  field:acr_tui.FDb.ind_style");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_style_buckets_n; i++) {
            acr_tui::FStyle* elem = _db.ind_style_buckets_elems[i];
            while (elem) {
                acr_tui::FStyle &row        = *elem;
                acr_tui::FStyle* next       = row.ind_style_next;
                u32 index          = row.ind_style_hashval & (new_nbuckets-1);
                row.ind_style_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_style_buckets_elems, old_size);
        _db.ind_style_buckets_elems = new_buckets;
        _db.ind_style_buckets_n = new_nbuckets;
    }
}

