acr_tui::FWidget* acr_tui::widget_AllocMaybe() {
    acr_tui::FWidget *row = (acr_tui::FWidget*)widget_AllocMem();
    if (row) {
        new (row) acr_tui::FWidget; // call constructor
    }
    return row;
}

// --- acr_tui.FDb.widget.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
acr_tui::FWidget* acr_tui::widget_InsertMaybe(const ui::Widget &value) {
    acr_tui::FWidget *row = &widget_Alloc(); // if out of memory, process dies. if input error, return NULL.
    widget_CopyIn(*row,const_cast<ui::Widget&>(value));
    bool ok = widget_XrefMaybe(*row); // this may return false
    if (!ok) {
        widget_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- acr_tui.FDb.widget.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* acr_tui::widget_AllocMem() {
    u64 new_nelems     = _db.widget_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    acr_tui::FWidget*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.widget_lary[bsr];
        if (!lev) {
            lev=(acr_tui::FWidget*)algo_lib::malloc_AllocMem(sizeof(acr_tui::FWidget) * (u64(1)<<bsr));
            _db.widget_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.widget_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- acr_tui.FDb.widget.RemoveAll
// Remove all elements from Lary
void acr_tui::widget_RemoveAll() {
    for (u64 n = _db.widget_n; n>0; ) {
        n--;
        widget_qFind(u64(n)).~FWidget(); // destroy last element
        _db.widget_n = i32(n);
    }
}

// --- acr_tui.FDb.widget.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void acr_tui::widget_RemoveLast() {
    u64 n = _db.widget_n;
    if (n > 0) {
        n -= 1;
        widget_qFind(u64(n)).~FWidget();
        _db.widget_n = i32(n);
    }
}

