void acr_tui::ind_binding_Reserve(int n) {
    ind_binding_AbsReserve(_db.ind_binding_n + n);
}

// --- acr_tui.FDb.ind_binding.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void acr_tui::ind_binding_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_binding_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(acr_tui::FBinding*);
        u32 new_size = new_nbuckets * sizeof(acr_tui::FBinding*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        acr_tui::FBinding* *new_buckets = (acr_tui::FBinding**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("acr_tui.out_of_memory  field:acr_tui.FDb.ind_binding");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_binding_buckets_n; i++) {
            acr_tui::FBinding* elem = _db.ind_binding_buckets_elems[i];
            while (elem) {
                acr_tui::FBinding &row        = *elem;
                acr_tui::FBinding* next       = row.ind_binding_next;
                u32 index          = row.ind_binding_hashval & (new_nbuckets-1);
                row.ind_binding_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_binding_buckets_elems, old_size);
        _db.ind_binding_buckets_elems = new_buckets;
        _db.ind_binding_buckets_n = new_nbuckets;
    }
}

// --- acr_tui.FDb.column.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
acr_tui::FColumn& acr_tui::column_Alloc() {
    acr_tui::FColumn* row = column_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("acr_tui.out_of_mem  field:acr_tui.FDb.column  comment:'Alloc failed'");
    }
    return *row;
}

// --- acr_tui.FDb.column.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
acr_tui::FColumn* acr_tui::column_AllocMaybe() {
    acr_tui::FColumn *row = (acr_tui::FColumn*)column_AllocMem();
    if (row) {
        new (row) acr_tui::FColumn; // call constructor
    }
    return row;
}

// --- acr_tui.FDb.column.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
acr_tui::FColumn* acr_tui::column_InsertMaybe(const ui::Column &value) {
    acr_tui::FColumn *row = &column_Alloc(); // if out of memory, process dies. if input error, return NULL.
    column_CopyIn(*row,const_cast<ui::Column&>(value));
    bool ok = column_XrefMaybe(*row); // this may return false
    if (!ok) {
        column_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- acr_tui.FDb.column.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* acr_tui::column_AllocMem() {
    u64 new_nelems     = _db.column_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    acr_tui::FColumn*  lev   = NULL;
    if (bsr < 32) {
        lev = _db.column_lary[bsr];
        if (!lev) {
            lev=(acr_tui::FColumn*)algo_lib::malloc_AllocMem(sizeof(acr_tui::FColumn) * (u64(1)<<bsr));
            _db.column_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.column_n = i32(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- acr_tui.FDb.column.RemoveAll
// Remove all elements from Lary
void acr_tui::column_RemoveAll() {
    for (u64 n = _db.column_n; n>0; ) {
        n--;
        column_qFind(u64(n)).~FColumn(); // destroy last element
        _db.column_n = i32(n);
    }
}

// --- acr_tui.FDb.column.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void acr_tui::column_RemoveLast() {
    u64 n = _db.column_n;
    if (n > 0) {
        n -= 1;
        column_qFind(u64(n)).~FColumn();
        _db.column_n = i32(n);
    }
}

// --- acr_tui.FDb.column.InputMaybe
static bool acr_tui::column_InputMaybe(ui::Column &elem) {
    bool retval = true;
    retval = column_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- acr_tui.FDb.column.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool acr_tui::column_XrefMaybe(acr_tui::FColumn &row) {
    bool retval = true;
    (void)row;
    // insert column into index ind_column
    if (true) { // user-defined insert condition
        bool success = ind_column_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "acr_tui.duplicate_key  xref:acr_tui.FDb.ind_column"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

