acr_tui::FColumn* acr_tui::ind_column_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_column_buckets_n - 1);
    acr_tui::FColumn *ret = _db.ind_column_buckets_elems[index];
    for (; ret && !((*ret).column == key); ret = ret->ind_column_next) {
    }
    return ret;
}

// --- acr_tui.FDb.ind_column.FindX
// Look up row by key and return reference. Throw exception if not found
acr_tui::FColumn& acr_tui::ind_column_FindX(const algo::strptr& key) {
    acr_tui::FColumn* ret = ind_column_Find(key);
    vrfy(ret, tempstr() << "acr_tui.key_error  table:ind_column  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- acr_tui.FDb.ind_column.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
acr_tui::FColumn& acr_tui::ind_column_GetOrCreate(const algo::strptr& key) {
    acr_tui::FColumn* ret = ind_column_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &column_Alloc();
        (*ret).column = key;
        bool good = column_XrefMaybe(*ret);
        if (!good) {
            column_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "acr_tui.create_error  table:ind_column  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- acr_tui.FDb.ind_column.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool acr_tui::ind_column_InsertMaybe(acr_tui::FColumn& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_column_next == (acr_tui::FColumn*)-1)) {// check if in hash already
        row.ind_column_hashval = algo::Smallstr50_Hash(0, row.column);
        ind_column_Reserve(1);
        u32 index = row.ind_column_hashval & (_db.ind_column_buckets_n - 1);
        acr_tui::FColumn* *prev = &_db.ind_column_buckets_elems[index];
        do {
            acr_tui::FColumn* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).column == row.column) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_column_next;
        } while (true);
        if (retval) {
            row.ind_column_next = *prev;
            _db.ind_column_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- acr_tui.FDb.ind_column.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void acr_tui::ind_column_Remove(acr_tui::FColumn& row) {
    if (LIKELY(row.ind_column_next != (acr_tui::FColumn*)-1)) {// check if in hash already
        u32 index = row.ind_column_hashval & (_db.ind_column_buckets_n - 1);
        acr_tui::FColumn* *prev = &_db.ind_column_buckets_elems[index]; // addr of pointer to current element
        while (acr_tui::FColumn *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_column_next; // unlink (singly linked list)
                _db.ind_column_n--;
                row.ind_column_next = (acr_tui::FColumn*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_column_next;
        }
    }
}

