acr_tui::FField* acr_tui::ind_field_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr100_Hash(0, key) & (_db.ind_field_buckets_n - 1);
    acr_tui::FField *ret = _db.ind_field_buckets_elems[index];
    for (; ret && !((*ret).field == key); ret = ret->ind_field_next) {
    }
    return ret;
}

