// --- acr_tui.FDb.ind_field.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
acr_tui::FField& acr_tui::ind_field_GetOrCreate(const algo::strptr& key) {
    acr_tui::FField* ret = ind_field_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &field_Alloc();
        (*ret).field = key;
        bool good = field_XrefMaybe(*ret);
        if (!good) {
            field_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "acr_tui.create_error  table:ind_field  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- acr_tui.FDb.ind_field.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool acr_tui::ind_field_InsertMaybe(acr_tui::FField& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_field_next == (acr_tui::FField*)-1)) {// check if in hash already
        row.ind_field_hashval = algo::Smallstr100_Hash(0, row.field);
        ind_field_Reserve(1);
        u32 index = row.ind_field_hashval & (_db.ind_field_buckets_n - 1);
        acr_tui::FField* *prev = &_db.ind_field_buckets_elems[index];
        do {
            acr_tui::FField* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).field == row.field) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_field_next;
        } while (true);
        if (retval) {
            row.ind_field_next = *prev;
            _db.ind_field_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- acr_tui.FDb.ind_field.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void acr_tui::ind_field_Remove(acr_tui::FField& row) {
    if (LIKELY(row.ind_field_next != (acr_tui::FField*)-1)) {// check if in hash already
        u32 index = row.ind_field_hashval & (_db.ind_field_buckets_n - 1);
        acr_tui::FField* *prev = &_db.ind_field_buckets_elems[index]; // addr of pointer to current element
        while (acr_tui::FField *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_field_next; // unlink (singly linked list)
                _db.ind_field_n--;
                row.ind_field_next = (acr_tui::FField*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_field_next;
        }
    }
}

