    _db.ind_style_buckets_n     	= 4; // (acr_tui.FDb.ind_style)
    _db.ind_style_buckets_elems 	= (acr_tui::FStyle**)algo_lib::malloc_AllocMem(sizeof(acr_tui::FStyle*)*_db.ind_style_buckets_n); // initial buckets (acr_tui.FDb.ind_style)
    if (!_db.ind_style_buckets_elems) {
        FatalErrorExit("out of memory"); // (acr_tui.FDb.ind_style)
    }
    memset(_db.ind_style_buckets_elems, 0, sizeof(acr_tui::FStyle*)*_db.ind_style_buckets_n); // (acr_tui.FDb.ind_style)
