    memset(_db.ind_widget_buckets_elems, 0, sizeof(acr_tui::FWidget*)*_db.ind_widget_buckets_n); // (acr_tui.FDb.ind_widget)
    // initialize LAry binding (acr_tui.FDb.binding)
