// --- acr_tui.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* acr_tui::value_ToCstr(const acr_tui::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case acr_tui_FieldId_value         : ret = "value";  break;
    }
    return ret;
}

// --- acr_tui.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void acr_tui::value_Print(const acr_tui::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- acr_tui.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool acr_tui::value_SetStrptrMaybe(acr_tui::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,acr_tui_FieldId_value); ret = true; break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- acr_tui.FieldId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void acr_tui::value_SetStrptr(acr_tui::FieldId& parent, algo::strptr rhs, acr_tui_FieldIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- acr_tui.FieldId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool acr_tui::value_ReadStrptrMaybe(acr_tui::FieldId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- acr_tui.FieldId..ReadStrptrMaybe
// Read fields of acr_tui::FieldId from an ascii string.
// The format of the string is the format of the acr_tui::FieldId's only field
bool acr_tui::FieldId_ReadStrptrMaybe(acr_tui::FieldId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

// --- acr_tui.FieldId..Print
// print string representation of ROW to string STR
// cfmt:acr_tui.FieldId.String  printfmt:Raw
void acr_tui::FieldId_Print(acr_tui::FieldId& row, algo::cstring& str) {
    acr_tui::value_Print(row, str);
}

