// --- acr_tui.TableId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void acr_tui::value_SetStrptr(acr_tui::TableId& parent, algo::strptr rhs, acr_tui_TableIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- acr_tui.TableId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool acr_tui::value_ReadStrptrMaybe(acr_tui::TableId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- acr_tui.TableId..ReadStrptrMaybe
// Read fields of acr_tui::TableId from an ascii string.
// The format of the string is the format of the acr_tui::TableId's only field
bool acr_tui::TableId_ReadStrptrMaybe(acr_tui::TableId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

